import torch
from safetensors.torch import load_file
import glob, os

ckpt_dir = '/root/autodl-tmp/checkpoints/exp008_sft/final'
sf_files = glob.glob(os.path.join(ckpt_dir, '*.safetensors'))
if sf_files:
    tensors = load_file(sf_files[0])
    for name, tensor in list(tensors.items())[:5]:
        print(f'{name}: {tensor.dtype}, shape={tensor.shape}')
    dtypes = set(t.dtype for t in tensors.values())
    print(f'\nAll dtypes in checkpoint: {dtypes}')
    if torch.bfloat16 in dtypes:
        print('OK Checkpoint is bf16')
    elif torch.float32 in dtypes:
        print('WARN Checkpoint is fp32!')
    elif torch.float16 in dtypes:
        print('OK Checkpoint is fp16')
else:
    bin_files = glob.glob(os.path.join(ckpt_dir, '*.bin'))
    if bin_files:
        state = torch.load(bin_files[0], map_location='cpu')
        for name, tensor in list(state.items())[:5]:
            print(f'{name}: {tensor.dtype}')
    print('Files in dir:', os.listdir(ckpt_dir))
